import { isKnownPermission, WILDCARD_PERMISSION } from "../permissions/catalog.js";
import { InvalidApiKeyError } from "./errors.js";
import type { ApiKey, ApiKeyRepository } from "./api-key.js";
import type { SecretHasher } from "../users/user.js";

export interface CreateApiKeyCommand {
  readonly id: string;
  readonly name: string;
  readonly scopes: readonly string[];
  /** Plaintext key generated by the caller (route layer — the domain never generates secrets). */
  readonly rawKey: string;
  readonly prefix: string;
  readonly createdBy: string;
  readonly createdAt: string;
}

function validate(cmd: CreateApiKeyCommand): string[] {
  const reasons: string[] = [];
  if (cmd.name.trim() === "") reasons.push("name is required");
  if (cmd.scopes.length === 0) reasons.push("at least one scope is required");
  for (const scope of cmd.scopes) {
    if (scope === WILDCARD_PERMISSION || !isKnownPermission(scope)) {
      reasons.push(`unknown permission scope "${scope}"`);
    }
  }
  if (cmd.rawKey.trim() === "") reasons.push("rawKey is required");
  if (cmd.prefix.trim() === "") reasons.push("prefix is required");
  return reasons;
}

/**
 * Issues a new API key. Hashes `rawKey` through the injected `SecretHasher`
 * port and never returns or stores the plaintext — the caller (route layer)
 * must return `rawKey` to the client itself, exactly once, before it is
 * discarded here.
 */
export async function createApiKey(
  cmd: CreateApiKeyCommand,
  repo: ApiKeyRepository,
  hasher: SecretHasher,
): Promise<ApiKey> {
  const reasons = validate(cmd);
  if (reasons.length > 0) throw new InvalidApiKeyError(reasons);

  const keyHash = await hasher.hash(cmd.rawKey);
  const key: ApiKey = {
    id: cmd.id,
    name: cmd.name,
    prefix: cmd.prefix,
    keyHash,
    scopes: [...new Set(cmd.scopes)],
    createdBy: cmd.createdBy,
    createdAt: cmd.createdAt,
    lastUsedAt: null,
    revokedAt: null,
  };
  await repo.save(key);
  return key;
}
